 record?"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><button class="button button-danger">Delete</button></form></div></td></tr><?php endforeach;?></tbody></table></div><p class="muted">Today/month and answered-message attribution starts after the AI usage reporting upgrade; lifetime usage retains the existing credential counter.</p><?php require dirname(__DIR__).'/partials/list_pagination.php';?><?php endif;?>
